<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Assets</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Fuel Cards</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <div class="d-flex mb-2">
      <div class="flex-grow-1 text-center">
        <div v-if="selectedProject">
          <h5 class="m-0">
            FUEL MANAGEMENT FOR {{ selectedProject?.short_name }} ({{
              selectedBudget?.name
            }})
          </h5>
        </div>
        <div v-else>
          <h5 class="m-0">FUEL MANAGEMENT</h5>
        </div>
      </div>
    </div>

    <div class="d-flex justify-content-center align-items-center gap-3 mt-2 mb-4">
      <button
        v-if="total_transactions > 0"
        class="btn btn-secondary text-white ms-4"
        @click.stop="ShowAssetDiv = !ShowAssetDiv"
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="26"
          height="26"
          fill="currentColor"
          class="bi bi-fuel-pump me-1"
          viewBox="0 0 16 16"
        >
          <path
            d="M3 2.5a.5.5 0 0 1 .5-.5h5a.5.5 0 0 1 .5.5v5a.5.5 0 0 1-.5.5h-5a.5.5 0 0 1-.5-.5z"
          />
          <path
            d="M1 2a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v8a2 2 0 0 1 2 2v.5a.5.5 0 0 0 1 0V8h-.5a.5.5 0 0 1-.5-.5V4.375a.5.5 0 0 1 .5-.5h1.495c-.011-.476-.053-.894-.201-1.25a2 2 0 0 0-.394-.569.5.5 0 0 1 .707-.707 3 3 0 0 1 .592.862c.217.428.301 1.01.301 1.664v7.127a1.5 1.5 0 0 1-3 0V10a1 1 0 0 0-1-1v5.5a.5.5 0 0 1-1 0V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v13h6.5a.5.5 0 0 1 0 1H.5a.5.5 0 0 1 0-1H1z"
          />
        </svg>
        : {{ total_transactions }}
