          title="Refresh page"
          :disabled="loading || loading_spinner"
          style="width: 2.5rem; height: 2.5rem"
        >
          <span v-if="loading || loading_spinner" v-html="loadingSpinner()"> </span>
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="16"
            height="16"
            fill="currentColor"
            class="bi bi-arrow-clockwise"
            viewBox="0 0 16 16"
          >
            <path
              fill-rule="evenodd"
              d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2v1z"
            />
            <path
              d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466z"
            />
          </svg>
        </button>
        <button
          class="btn btn-primary me-2"
          @click="asset_bincard = !asset_bincard"
          v-if="user_permissions.includes('can_register_asset_bincard') && selectedBudget"
        >
  
  <i  class="bi bi-plus-square fs-4"></i>
          
        </button>
        <button
          class="btn btn-outline-primary"
          data-bs-toggle="offcanvas"
          data-bs-target="#offcanvasWithBothOptions"
        >
          Select Project
        </button>
      </div>
    </div>

    <!-- No Records Message -->
    <div v-if="selectedProject && filteredData.length === 0" class="text-center my-4">
      <p class="mb-0">
        No records found for {{ selectedProject.short_name }} {{ selectedBudget?.name }}
      </p>
    </div>

    <div v-if="!selectedBudget" class="text-center my-4">
      <p class="mb-0">Please select a budget from the project list</p>
    </div>

    <div class="d-flex justify-content-start mb-3" v-if="ShowAssetDiv">
      <div class="card" ref="assetDivRef">
        <div class="card-body">
          <h8 class="card-title text-center text-dark">Assets Filled Today</h8>
          <div
            v-for="(asset, index) in assets_counts"
            :key="asset.id"
            class="list-group-item list-group-item-action d-flex align-items-center"
          >
            <span class="badge bg-secondary rounded-pill me-3">{{ index + 1 }}</span>
            <span class="fw-bold">{{ asset.name }} - {{ asset.type_name }}</span>
          </div>
        </div>
      </div>
    </div>

    <div
      class="offcanvas offcanvas-end"
      data-bs-scroll="true"
      tabindex="-1"
      id="offcanvasWithBothOptions"
    >
      <div class="offcanvas-header">
        <h5 class="offcanvas-title">PROJECT LISTS</h5>
        <button type="button" class="btn-close" data-bs-dismiss="offcanvas"></button>
      </div>

      <div class="offcanvas-body">
        <div class="row">
          <div class="col-12">
            <div class="list-group" id="list-tab" role="tablist">
              <span v-if="loading_spinner" v-html="waitIndicator()"></span>

              <div v-for="project in projects" :key="project.id" class="mb-1">
                <div
                  class="list-group-item d-flex justify-content-between align-items-center"
                  :class="{
                    active:
                      selectedProject &&
                      selectedProject.id === project.id &&
                      selectedBudget,
                  }"
                  @click="toggleProject(project)"
                  style="cursor: pointer"
                >
                  {{ project.short_name }}
                  <i
                    class="bi"
                    :class="
                      openedProjectId === project.id ? 'bi-chevron-up' : 'bi-chevron-down'
                    "
                  ></i>
                </div>

                <div v-if="openedProjectId === project.id" class="ms-3 mt-1 bg-light">
                  <div v-if="isBudgetsloading" class="text-muted small">
                    <span v-html="waitIndicator()"></span>
                  </div>

                  <div
                    v-for="b in budgets"
                    :key="b.id"
                    class="list-group-item list-group-item-action list-group-item-budget"
                    :class="{ active: selectedBudget && selectedBudget.id === b.id }"
                    @click="selectBudget(project, b)"
                    data-bs-dismiss="offcanvas"
                  >
                    {{ b.name }}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="my-4">
      <!-- item registration form starts -->
      <form
        v-if="asset_bincard"
        class="mt-3 p-3 border rounded bg-white shadow"
        @submit.prevent="registerBinCard"
      >
        <h4 class="text-center">REGISTER BIN CARD</h4>
        <div class="row mb-2">
          <div class="col-md-6">
            <label class="form-label">Select Asset</label>
            <Multiselect
              v-model="asset"
              :options="assets"
              label="name"
              track-by="id"
              placeholder="Select An Asset"
              :searchable="true"
              :close-on-select="true"
              required
            />
          </div>
        </div>
        <div class="text-center gap-2 justify-content-end">
          <button
            type="button"
            class="btn btn-danger me-3"
            @click="
              asset_bincard = false;
              resetForm();
            "
          >
            Cancel
          </button>
          <button type="submit" class="btn btn-primary" :disabled="loading">
            <span
              v-if="loading"
              class="spinner-border spinner-border-sm me-1"
              role="status"
              aria-hidden="true"
            ></span>
            <span v-else>Register</span>
          </button>
        </div>
      </form>
      <!-- item registration form ends-->
    </div>

    <!-- loading spinner starts -->
    <div v-if="loading_spinner" v-html="waitIndicator()"></div>
    <!-- Loading spinner ends -->

    <!-- Bin Cards List -->
    <div v-else class="accordion accordion-flush" id="accordionFlushExample">
      <!-- Issue from Fuel Station - always shown first -->
      <div class="accordion-item" v-if="selectedBudget">
        <h2 class="accordion-header">
          <button
            class="accordion-button"
            type="button"
            data-bs-toggle="collapse"
            data-bs-target="#flush-collapse-fuel-station"
            aria-expanded="true"
            aria-controls="flush-collapse-fuel-station"
          >
            <div class="d-flex w-100 justify-content-between align-items-center">
              <div class="d-flex flex-wrap">
                <span class="fw-bold">Issue from Fuel Station</span>&nbsp;&nbsp;&nbsp;
                <!-- <span>Records: {{ assetConsumptions.length }}</span> -->
              </div>
              <div class="d-flex align-items-center gap-2">
                <span class="fw-bold">{{ totalFuelStationQuantity }} LTs</span>
              </div>
            </div>
          </button>
        </h2>

        <div
          id="flush-collapse-fuel-station"
          class="accordion-collapse collapse"
          data-bs-parent="#accordionFlushExample"
        >
          <div class="accordion-body">
<div class="d-flex justify-content-end align-items-center gap-2 mb-3">
    <input
      type="date"
      v-model="fuelStationDateFilter.start"
      class="form-control form-control-sm"
      style="width: auto"
    />
    <span>to</span>
    <input
      type="date"
      v-model="fuelStationDateFilter.end"
      :min="fuelStationDateFilter.start"
      class="form-control form-control-sm"
      style="width: auto"
    />
    <button
      class="btn btn-sm btn-outline-secondary"
      @click="clearFuelStationFilter()"
      v-if="fuelStationDateFilter.start || fuelStationDateFilter.end"
    >
      Clear
    </button>
    <button 
  class="btn btn-success ms-2" 
  @click="printFuelIssueReport(getFuelStationFilteredData)"
>
  <i class="bi bi-printer fs-4"></i>
</button>
  </div>




            <div class="panel p-0 mt-3">
              <div class="row layout-top-spacing">
                <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
