                            <tr>
                              <th>Sno</th>
                              <th>Date</th>
                              <th>Asset</th>
                              <th>Item</th>
                              <th>Issuer</th>
                              <th>Quantity</th>
                              <th>Task</th>
                              <th>Initial Reading</th>
                              <th>Final Reading</th>
                              <th>Ratio</th>
                              <th>Work Target</th>
                              <th>Work Covered</th>
                              <th>Cost</th>
                              <th>actions</th>
                            </tr>
                          </thead>
                          <tbody>
                            <template
                    v-for="(consumption, index) in getFuelStationFilteredData"
                    :key="consumption.id"
                  >
                              <tr>
                                <td>{{ index + 1 }}</td>
                                <td>{{ formatDateOnly(consumption.date) }}</td>
                                <td>
                                  {{ consumption.machine_name }}
                                  {{ consumption.machine_type }}
                                </td>
                                <td>{{ consumption.item_name }}</td>
                                <td>{{ consumption.issuer_name }}</td>
                                <td>
                                  {{ Number(consumption.quantity).toLocaleString() }} ltrs
                                </td>
                                <td>
                                  {{
                                    consumption.task ?? consumption.fuelLog?.task ?? "--"
                                  }}
                                </td>
                                <td>{{ consumption.initial_reading ?? "--" }}</td>
                                <td>{{ consumption.final_reading ?? "--" }}</td>
                                <td>
                                  {{ consumption.machine_average_ratio ?? "--" }}
                                  {{ consumption.machine_consumption_type ?? "" }}
                                </td>
                                <td>{{ consumption.fuelLog?.work_target ?? "--" }}</td>
                                <td>{{ consumption.fuelLog?.work_covered ?? "--" }}</td>
                                <td>
                                  {{
                                    formatNumber(consumption.rate * consumption.quantity)
                                  }}
                                </td>
                                <td class="text-center">
                                  <div class="btn-group">
                                    <a
                                      href="javascript:;"
                                      class="edit me-2"
                                      @click="openWorkTargetModal(consumption)"
                                      data-bs-toggle="modal"
                                      data-bs-target="#work-target-modal"
                                      v-if="
                                        user_permissions.includes(
                                          'can_edit_asset_bincard_transactions'
                                        )
                                      "
                                    >
                                      <svg
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        fill="currentColor"
                                        class="bi bi-eye text-primary"
                                        viewBox="0 0 16 16"
                                      >
                                        <path
                                          d="M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z"
                                        />
                                        <path
                                          d="M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0"
                                        />
                                      </svg>
                                    </a>
                                  </div>
                                </td>
                              </tr>
                              <tr v-if="consumption.remark">
                                <td colspan="1"></td>
                                <td colspan="12" class="bg-white text-danger">
                                  <strong>Remark:</strong> <i>{{ consumption.remark }}</i>
                                </td>
                              </tr>
                            </template>
                            <tr v-if="assetConsumptions.length === 0">
                              <td colspan="13" class="text-center">
                                No fuel station issues found
                              </td>
                            </tr>
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="accordion-item" v-for="(card, index) in filteredData" :key="card.id">
        <h2 class="accordion-header">
          <button
            class="accordion-button collapsed"
            type="button"
            data-bs-toggle="collapse"
            :data-bs-target="'#flush-collapse-' + index"
            aria-expanded="false"
            :aria-controls="'flush-collapse-' + index"
          >
