              <!-- Left side content -->
              <div class="d-flex flex-wrap">
                <span>{{ card?.asset }}</span
                >&nbsp;&nbsp;&nbsp;
                <span>Consumption Type: {{ card?.consuption_type || "--" }}</span
                >&nbsp;&nbsp;&nbsp;
                <span>Balance: {{ Number(card.balance).toLocaleString() }} ltrs</span>
              </div>

