              <div class="d-flex align-items-center gap-2">
                <span class="fw-bold"
                  >{{ card.budget?.name }}
                  {{ Number(card.bincard_increments).toLocaleString() }} LTs</span
                >
                <a
                  href="javascript:;"
                  class="text-danger me-3"
                  @click="deleteBinCard(card)"
                  v-if="user_permissions.includes('can_delete_asset_bincard')"
                >
                <i class="bi bi-trash fs-4"></i>
                </a>
              </div>
            </div>
          </button>
        </h2>

        <div
          :id="'flush-collapse-' + index"
          class="accordion-collapse collapse"
          data-bs-parent="#accordionFlushExample"
        >
          <div class="accordion-body">
            <div class="d-flex justify-content-end align-items-center gap-2 mb-3">
  <input
    type="date"
    v-model="getCardDateFilter(card.id).start"
    class="form-control form-control-sm"
    style="width: auto"
  />
  <span>to</span>
  <input
    type="date"
    v-model="getCardDateFilter(card.id).end"
    :min="getCardDateFilter(card.id).start"
    class="form-control form-control-sm"
    style="width: auto"
  />
  <button
    class="btn btn-sm btn-outline-secondary"
    @click="clearCardDateFilter(card.id)"
    v-if="cardDateFilters[card.id]?.start || cardDateFilters[card.id]?.end"
  >
    Clear
  </button>

  <button
    class="btn btn-primary"
    data-bs-toggle="modal"
    data-bs-target="#add-item-modal"
    @click="openAddTransactionModal(card)"
    v-if="user_permissions.includes('can_register_asset_bincard')"
  >
    <i class="bi bi-plus-square fs-4"></i>
  </button>
  <button 
  class="btn btn-success ms-2 me-2" 
  @click="printBinCardWithFilter(card)"
>
  <i class="bi bi-printer fs-4"></i>
</button> 
<button class="btn btn-info" @click="exportToExcelBinCardWithFilter(card)">
      <i class="bi bi-file-earmark-spreadsheet  fs-4"></i>
    </button>

</div>

            <div class="panel p-0 mt-3">
              <div class="row layout-top-spacing">
                <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                  <div class="panel p-0">
