                      <div class="table-responsive">
                        <table class="table table-striped table-hover align-middle">
                          <thead class="table-dark">
                            <tr>
                              <th>Sno</th>
                              <th>Date</th>
                              <th>Action</th>
                              <th>Quantity</th>
                              <th>Task</th>
                              <th>Initial Reading</th>
                              <th>Final Reading</th>
                              <th>Expected Ratio</th>
                              <th>Work Target</th>
                              <th>Work Covered</th>
                              <th>Balance</th>
                               <th>issuer</th>
                              <th class="text-center">Actions</th>
                            </tr>
                          </thead>
                          <tbody>
                            <template v-for="(transaction, index) in getFilteredTransactions(card)" :key="transaction.id">
                              <tr v-if="transaction.asset">
                                <td colspan="1"></td>
                                <td
                                  v-if="card.asset_id == 0"
                                  colspan="3"
                                  class="bg-white text-dark fw-bold"
                                >
                                  <strong>Asset :</strong> {{ transaction?.asset?.name }}
                                  {{ transaction?.asset?.type_name }}
                                  <svg
                                    xmlns="http://www.w3.org/2000/svg"
                                    width="16"
                                    height="16"
                                    fill="currentColor"
                                    class="bi bi-arrow-90deg-down fw-bold"
                                    viewBox="0 0 16 16"
                                    transform="scale(-1 1) translate(-16 0)"
                                  >
                                    <path
                                      fill-rule="evenodd"
                                      d="M4.854 14.854a.5.5 0 0 1-.708 0l-4-4a.5.5 0 0 1 .708-.708L4 13.293V3.5A2.5 2.5 0 0 1 6.5 1h8a.5.5 0 0 1 0 1h-8A1.5 1.5 0 0 0 5 3.5v9.793l3.146-3.147a.5.5 0 0 1 .708.708z"
                                    />
                                  </svg>
                                </td>
                              </tr>
                              <tr>
                                <td @click="showMessage(transaction.id)">
                                  {{ index + 1 }}
                                </td>
                                <td>{{ transaction.date }}</td>
                                <td>{{ transaction.action }}</td>
                                <td>{{ Number(transaction.quantity).toLocaleString() }}LTS</td>
                                <td>{{ transaction.task }}</td>
                                <td>{{ transaction.initial_reading }}</td>
                                <td>{{ transaction.final_reading }}</td>
                                <td>{{ transaction?.ratio ?? "---" }}</td>
                                <td>
                                  {{ transaction.work_target }} {{ transaction.unit }}
                                </td>
                                <td>
                                  {{ transaction.work_covered ?? 0 }}
                                  {{ transaction.unit }}
                                </td>
                                <td>{{ Number(transaction.balance).toLocaleString() }}LTS</td>
                                 <td>{{ transaction.issuer }}</td>
                                <td class="text-center">
                                  <div class="btn-group">
                                    <a
                                      href="javascript:;"
                                      class="edit me-2"
                                      @click="openEditModal(transaction)"
                                      data-bs-toggle="modal"
                                      data-bs-target="#edit-transaction-modal"
                                      v-if="
                                        user_permissions.includes(
                                          'can_edit_asset_bincard_transactions'
                                        )
                                      "
                                    >
                                    <i class="bi bi-eye text-primary fs-4"></i>
                                    </a>
                                    <a
                                      href="javascript:;"
                                      class="text-danger me-3"
                                      @click.stop="deleteBinCardTransaction(transaction)"
                                      v-if="
                                        user_permissions.includes(
                                          'can_delete_asset_bincard'
                                        )
                                      "
                                    >
                                      <svg
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="20"
                                        height="20"
                                        fill="currentColor"
                                        class="bi bi-trash"
                                        viewBox="0 0 16 16"
                                      >
                                        <path
                                          d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
                                        />
                                        <path
                                          d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
                                        />
                                      </svg>
                                    </a>
                                  </div>
                                </td>
                              </tr>
                              <tr v-if="transaction.description">
                                <td colspan="1"></td>
                                <td colspan="8" class="bg-white text-danger">
                                  <strong>Remark:</strong>
                                  <i>{{ transaction?.description }}</i>
                                </td>
                              </tr>
                            </template>
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

