      class="modal fade mymodal"
      id="add-item-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="itemModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="itemModalLabel">
              Create Bin Card Transaction for {{ selectedCard?.asset }}
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="closebinCardModal()"
              id="close_item"
            ></button>
          </div>
          <form @submit.prevent="addTransaction()">
            <div class="modal-body">
              <div class="row mb-3">
                <div class="col-md-3">
                  <label for="direction">Transaction Type</label>
                  <Multiselect
                    v-model="direction"
                    :options="directions"
                    label="label"
                    track-by="value"
                    placeholder="Select Direction"
                    :searchable="true"
                    :allow-empty="false"
