const cardDateFilters = ref({});

const getCardDateFilter = (cardId) => {
  if (!cardDateFilters.value[cardId]) {
    cardDateFilters.value[cardId] = { start: "", end: "" };
  }
  return cardDateFilters.value[cardId];
};

const isWithinDateRange = (dateStr, start, end) => {
  if (!dateStr) return false;
  if (!start && !end) return true;

  const d = new Date(dateStr);
  d.setHours(0, 0, 0, 0);

  if (start) {
    const s = new Date(start);
    s.setHours(0, 0, 0, 0);
    if (d < s) return false;
  }
  if (end) {
    const e = new Date(end);
    e.setHours(0, 0, 0, 0);
    if (d > e) return false;
  }
  return true;
};

const getFilteredTransactions = (card) => {
  const f = cardDateFilters.value[card.id];
  if (!f || (!f.start && !f.end)) return card.transactions;
  return card.transactions.filter((tx) => isWithinDateRange(tx.date, f.start, f.end));
};

const clearCardDateFilter = (cardId) => {
  if (cardDateFilters.value[cardId]) {
    cardDateFilters.value[cardId].start = "";
    cardDateFilters.value[cardId].end = "";
  }
};


const fuelStationDateFilter = ref({ start: "", end: "" });

const getFuelStationFilteredData = computed(() => {
  const { start, end } = fuelStationDateFilter.value;
  if (!start && !end) return assetConsumptions.value;
  
  return assetConsumptions.value.filter(consumption => 
    isWithinDateRange(consumption.date, start, end)
  );
});

// Update total to use filtered data
const totalFuelStationQuantity = computed(() => {
  const data = getFuelStationFilteredData.value;
  return data
    .reduce((sum, item) => sum + parseFloat(item.quantity || 0), 0)
    .toLocaleString();
});

const clearFuelStationFilter = () => {
  fuelStationDateFilter.value.start = "";
  fuelStationDateFilter.value.end = "";
};

const printBinCardWithFilter = (card) => {
  // Get filtered transactions for this card
  const filteredTransactions = getFilteredTransactions(card);
  
  // Create a copy of the card with filtered transactions
  const filteredCard = {
    ...card,
    transactions: filteredTransactions
  };
  
  // Call the injected print function
  printBinCard(filteredCard);
};

const exportToExcelBinCardWithFilter = (card) => {
  // Get filtered transactions for this card
  const filteredTransactions = getFilteredTransactions(card);
  
  // Create a copy of the card with filtered transactions
  const filteredCard = {
    ...card,
    transactions: filteredTransactions
  };
  
  // Call the injected print function
  exportBinCardToExcel(filteredCard);
};

</script>
